/*
 * "CHECK-IN ANSWERED" ENDS WHEN THE COACH SAYS SO (DBU-10). Reading the answers is the whole of
 * the work here, so unlike a question, the item ends on "Done", which stamps seenAt. A second press
 * keeps the first stamp. Rings a staff-only bell so every open inbox re-reads.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 2, plain: true });
    const id = String(Inputs.responseId || '');
    const found = id ? await q('CheckinResponse', { objectId: { equalTo: id } }) : [];
    const r = found[0];
    if (!r) return refuse('These answers could not be found. Reload the page.');
    if (!r.seenAt) await Noodl.Records.save(r.objectId, { seenAt: new Date().toISOString() }, { className: 'CheckinResponse' });
    await Noodl.Records.create('Doorbell', { learner: r.learner, topic: 'inbox' }, { acl: { 'role:staff': { read: true } } });
    Outputs.done();
  } catch (e) {
    console.error('[dbu:settleCheckin]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
